from mudlab.generic.io import get_case_insensitive_glob

from mudlab.file_parsers.json_parser import JSONParser

from .namespace import project_parsers

@project_parsers.register_parser()
class JSONProjectParser(JSONParser):

    description = "MudLab project (*.MUD)"
    extensions = get_case_insensitive_glob("*.MUD")
    mimetypes = ["application/octet-stream", "application/zip"]


    @classmethod
    def _parse_data(cls, filename, fp, data_objects=None, close=True):
        # A project owns the (per-thread) object pool for its lifetime, so
        # clear it before decoding this one. Otherwise a project already in the
        # pool - e.g. a batch / headless run that loads several files in one
        # process - collides on shared uuids, and ObjectPool.add_object
        # re-uuids the INCOMING object ("will break refs", per its own
        # comment), leaving atom-type / specimen / phase references dangling
        # (zero structure factor -> blank pattern). This is the parser-level
        # guard that covers EVERY caller, including headless scripts that call
        # JSONProjectParser.parse() directly (the GUI also clears on open/new).
        # Lazy import to avoid a parser<->project import cycle.
        from mudlab.project.models import Project
        type(Project).object_pool.clear()
        project = super(JSONProjectParser, cls)._parse_data(filename, fp, data_objects=data_objects, close=close)
        project.filename = filename
        return project

    pass #end of class
